                id = "TOKEN-004",
                from = "ACTIVE",
                event = "EXPIRE",
                to = "REVOCATION_REQUESTED",
                guard = "epochCurrent",
                actions = listOf("bumpEpochAndReject", "persistToken", "appendAudit"),
            ),
            FsmTransition(
                id = "TOKEN-005",
                from = "REVOCATION_REQUESTED",
                event = "BEGIN_DRAIN",
                to = "DRAINING",
                guard = "true",
                actions = listOf("drainOwnedState"),
            ),
            FsmTransition(
                id = "TOKEN-006",
                from = "DRAINING",
                event = "DRAIN_COMPLETE",
                to = "REVOKED",
                guard = "noOldUse && terminalTargetRevoked",
                actions = listOf("erasePlaintextReceipt", "persistToken", "appendAudit"),
            ),
            FsmTransition(
                id = "TOKEN-007",
                from = "DRAINING",
                event = "DRAIN_COMPLETE",
                to = "EXPIRED",
                guard = "noOldUse && terminalTargetExpired",
                actions = listOf("erasePlaintextReceipt", "persistToken", "appendAudit"),
            ),
        ),
    )

    val ALL: List<FsmMachineDefinition> = listOf(
        REQUEST,
        SESSION,
        RESERVATION,
        JOB,
        MODEL_INSTALLATION,
        LOADED_MODEL,
        COMMIT,
        RUNTIME,
        REVOCATION,
        ASSET,
        CLIENT_REGISTRATION,
        OPERATION,
        ENGINE_MODULE,
        ALLOCATION,
        REVISION_LEASE,
        COMMAND,
        PAIRING_CHALLENGE,
        LAN_SERVICE,
        CONTENT_REPORT,
        TOKEN,
    )

    private val byId: Map<String, FsmMachineDefinition> = ALL.associateBy { it.id }

    fun get(id: String): FsmMachineDefinition? = byId[id]

    fun require(id: String): FsmMachineDefinition =
        byId[id] ?: error("Unknown state machine (fail closed): $id")
}
